using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using Astrea.BattleActions;
using Astrea.GameElements;
using UnityEngine;

namespace Astrea;

public class ModHelper : ReferenceSingleton<ModHelper>
{
	[SerializeField]
	private DiceActionLogicsList diceActionLogicsList;

	[SerializeField]
	private BattleActionsList battleActionsList;

	private List<BattleAction> battleActionsMod = new List<BattleAction>();

	public DiceActionLogicsList DiceActionLogicsList => diceActionLogicsList;

	public BattleActionsList BattleActionsList => battleActionsList;

	public void CreateBattleAction(BattleAction battleAction)
	{
		battleAction.SetupModdedBattleAction();
		battleActionsMod.Add(battleAction);
	}

	public void Initialize()
	{
		battleActionsList.battleActions.AddRange(battleActionsMod);
	}

	public Sprite GetModSprite(Assembly assembly, string spriteName)
	{
		try
		{
			string text = assembly.GetName().Name + ".Resources." + spriteName;
			using Stream stream = assembly.GetManifestResourceStream(text);
			byte[] array = new byte[16384];
			using MemoryStream memoryStream = new MemoryStream();
			int count;
			while ((count = stream.Read(array, 0, array.Length)) > 0)
			{
				memoryStream.Write(array, 0, count);
			}
			Texture2D texture2D = new Texture2D(1, 1);
			texture2D.LoadImage(memoryStream.ToArray());
			return Sprite.Create(texture2D, new Rect(0f, 0f, texture2D.width, texture2D.height), Vector2.one * 0.5f);
		}
		catch (Exception)
		{
		}
		return null;
	}
}
